structure.mermaidSource:
flowchart TD
  start["Início: Vocábulos sob Análise"] --> dec_grafia{"As palavras possuem EXATAMENTE as mesmas letras?"}
  dec_grafia -- "Não" --> res_heterografos["Descartar Polissemia: Homófonos Heterógrafos"]
  dec_grafia -- "Sim" --> dec_fonetica{"A pronúncia e o timbre vocálico são IDÊNTICOS?"}
  dec_fonetica -- "Não" --> res_heterofonos["Descartar Polissemia: Homógrafos Heterófonos"]
  dec_fonetica -- "Sim" --> dec_semantica{"Os significados nos contextos são DIVERGENTES?"}
  dec_semantica -- "Não" --> res_repeticao["Mesma Palavra: Repetição Lexical Unívoca"]
  dec_semantica -- "Sim" --> res_polissemia["Confirma-se Polissemia / Homonímia Perfeita"]

flowchart TD
  start["Início: Análise Concorrente (Polissemia vs. Homonímia)"] --> dec_identidade{"Há identidade total de grafia e de pronúncia?"}
  dec_identidade -- "Não (Divergência gráfica ou fônica)" --> res_homo_imperf["Homonímia Imperfeita: Homógrafo ou Homófono"]
  dec_identidade -- "Sim (Mesma grafia e mesmo som)" --> dec_raiz{"Compartilham étimo comum ou raiz semântica?"}
  dec_raiz -- "Não (Etimologias independentes)" --> res_homo_perf["Homonímia Perfeita: Origens Distintas"]
  dec_raiz -- "Sim (Raiz/étimo comum)" --> dec_banca{"Polissemia e Homonímia disputam alternativas na mesma questão?"}
  dec_banca -- "Sim (Opções concorrentes)" --> proc_especificidade["Aplicar o Critério da Máxima Especificidade"]
  dec_banca -- "Não (Apenas uma opção disponível)" --> dec_disponivel{"Qual opção consta na questão?"}
  proc_especificidade --> res_gabarito_poli["Gabarito Técnico Definitivo: POLISSEMIA"]
  dec_disponivel -- "Polissemia" --> res_gabarito_poli
  dec_disponivel -- "Apenas Homonímia" --> res_homo_lato["Gabarito Residual: Homonímia em Sentido Lato"]
